import{_ as e,o,c as a,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Optimizing Teuthology- Turning Failures into faster Ceph Fixes","description":"","frontmatter":{"title":"Optimizing Teuthology- Turning Failures into faster Ceph Fixes","date":"2026-07-09T00:00:00.000Z","updated":"2026-07-10T00:00:00.000Z","tags":["Ceph","Teuthology","CI/CD","测试","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2026/Optimizing_Teuthology_-_Turning_Failures_into_faster_Ceph_Fixes.md","filePath":"posts/2026/Optimizing_Teuthology_-_Turning_Failures_into_faster_Ceph_Fixes.md","lastUpdated":null}'),s={name:"posts/2026/Optimizing_Teuthology_-_Turning_Failures_into_faster_Ceph_Fixes.md"};function i(l,t,n,h,d,g){return o(),a("div",null,[...t[0]||(t[0]=[r('<h2 id="演讲概述" tabindex="-1">演讲概述 <a class="header-anchor" href="#演讲概述" aria-label="Permalink to &quot;演讲概述&quot;">​</a></h2><p>本次演讲由 Lee Sanders 主讲，Lee 是一位性能方向的专家，但本次分享的主题聚焦于 <strong>Teuthology</strong> ——Ceph 项目的集成测试框架。演讲核心内容是：如何将测试失败快速转化为有效的 Ceph 问题修复，从而提升开发效率和测试资源利用率。</p><h2 id="teuthology-简介" tabindex="-1">Teuthology 简介 <a class="header-anchor" href="#teuthology-简介" aria-label="Permalink to &quot;Teuthology 简介&quot;">​</a></h2><p>Teuthology 是 Ceph 社区使用的大规模测试框架，运行在一个大型测试实验室中（近期已迁移至 IBM 基础设施）。其主要功能包括：</p><ul><li>允许开发者在 PR 合并前自动调度测试任务</li><li>通过运行测试套件检测回归问题</li><li>为 PR 交付提供质量保障</li></ul><h2 id="问题背景-dead-job-的困境" tabindex="-1">问题背景：Dead Job 的困境 <a class="header-anchor" href="#问题背景-dead-job-的困境" aria-label="Permalink to &quot;问题背景：Dead Job 的困境&quot;">​</a></h2><p>Lee 的团队在开发 <strong>Fast Erasure Coding（Fast EC）</strong> 功能的早期阶段，引入了大量 Bug。在使用 FIO、<code>rados bench</code>、<code>self-test rados</code> 等 IO 压测工具注入 IO 时，频繁出现 OSD assert 和客户端挂起的情况。</p><p><strong>核心问题</strong>：Teuthology 的 watchdog 未能及时检测到 OSD assert，导致出现 <strong>dead job</strong>（区别于 failed job）：</p><ul><li><strong>Failed job</strong>：测试已知失败，立即返回结果</li><li><strong>Dead job</strong>：任务未超时，系统资源被占用，开发者无法获得结果，单个 dead job 可持续约 <strong>8 小时</strong></li></ul><p>这不仅浪费了开发者的等待时间，也大量消耗了测试实验室的机器资源（系统被占用但实际上什么都没执行）。</p><h2 id="teuthology-job-的执行结构" tabindex="-1">Teuthology Job 的执行结构 <a class="header-anchor" href="#teuthology-job-的执行结构" aria-label="Permalink to &quot;Teuthology Job 的执行结构&quot;">​</a></h2><p>一个典型的 Teuthology Job 包含五个执行线程：</p><table tabindex="0"><thead><tr><th>线程</th><th>功能描述</th></tr></thead><tbody><tr><td><strong>主 IO 线程</strong></td><td>创建存储池、执行 IO、清理测试环境</td></tr><tr><td><strong>Daemon 启动线程</strong></td><td>启动 OSD、MON、MDS 等 Ceph 守护进程</td></tr><tr><td><strong>Watchdog 线程</strong></td><td>监控守护进程状态，负责失败时协调其他线程清理</td></tr><tr><td><strong>Thrasher 线程</strong></td><td>人为注入错误（如 kill OSD/MON/MGR），模拟故障场景</td></tr><tr><td><strong>监控线程</strong></td><td>检测集群错误和 IO 错误</td></tr></tbody></table><p>原有实现中，watchdog 与其他线程之间缺乏有效的联动机制，导致失败发生后无法及时通知并清理其他线程。</p><h2 id="改进措施" tabindex="-1">改进措施 <a class="header-anchor" href="#改进措施" aria-label="Permalink to &quot;改进措施&quot;">​</a></h2><p>针对上述问题，团队在红色标注的关键路径上做了以下改进：</p><ol><li><p><strong>增强 Watchdog 对 OSD assert 的响应</strong>：新增 watcher 逻辑，能够监听来自 Thrasher 和集群日志的错误信号，并在检测到 OSD assert 时立即通知 IO 客户端退出。</p></li><li><p><strong>优化测试清理流程</strong>：跳过几乎必然挂死的清理步骤（如在测试已失败时尝试删除存储池），直接进入集群删除流程，大幅缩短清理耗时。</p></li><li><p><strong>改善失败原因上报</strong>：将原本混乱的 Python traceback 替换为更具可读性的失败信息，明确指出是哪个 Thrasher 进程和哪个 Ceph 守护进程（OSD/MON 等）触发了失败，方便开发者和 QA 审查人员快速定位问题。</p></li></ol><h2 id="改进效果" tabindex="-1">改进效果 <a class="header-anchor" href="#改进效果" aria-label="Permalink to &quot;改进效果&quot;">​</a></h2><p>上述改进的核心 PR 已合并，带来以下显著收益：</p><ul><li><strong>Dead job 转变为 Fast failure</strong>：在错误发生的时间点即可获得失败结果，系统资源可以更快释放并复用</li><li><strong>Dead job 数量大幅降低</strong>：不再需要等待 8 小时超时</li><li><strong>测试实验室资源利用率提升</strong>：空闲的机器可以更快投入下一个队列中的 Job</li><li><strong>开发者效率提升</strong>：更快获取测试结果，加速 PR 迭代</li></ul><h2 id="qa-审查效率提升" tabindex="-1">QA 审查效率提升 <a class="header-anchor" href="#qa-审查效率提升" aria-label="Permalink to &quot;QA 审查效率提升&quot;">​</a></h2><p>作为 QA 审查人员，Lee 提到在一个包含 300 个 Job 的套件中，过去需要约 <strong>2 天时间</strong>来筛查约 <strong>80 个失败</strong>，其中大量是重复的已知问题或误报（false alarm）。经过改进后，误报数量已降低至约 <strong>30 个</strong>，但仍有进一步优化空间。</p><h2 id="对社区的呼吁" tabindex="-1">对社区的呼吁 <a class="header-anchor" href="#对社区的呼吁" aria-label="Permalink to &quot;对社区的呼吁&quot;">​</a></h2><p>Lee 向社区提出以下建议：</p><blockquote><p>如果你在合并 PR 时发现与你的变更无关的测试失败，请考虑主动调查并提交修复 PR。这不仅是在帮助整个社区，也是在节省你自己筛查无关失败的时间。</p></blockquote><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本次分享展示了 Teuthology 测试框架在 Ceph 开发流程中的重要性，以及通过改善线程间联动、优化清理逻辑、提升失败信息可读性等手段，将 dead job 转化为快速失败通知的实践成果。这一系列改进对于提升 Ceph 社区整体的开发效率和 CI/CD 质量具有重要意义。</p>',27)])])}const _=e(s,[["render",i]]);export{u as __pageData,_ as default};
